SELECT * FROM S10T001T
WHERE
    APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
AND SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
AND (   SKYSHIMEDYDM = '000000'
    OR  SKYSHIMEDYDM IS NULL)
AND (   SKYPRCSJISSIDD = '00000000'
    OR  SKYPRCSJISSIDD IS NULL)
AND YUKOKBN = #{yukokbn,jdbcType=VARCHAR}

SELECT
    SUM(NVL(NMST.NYKNKIN, 0)) + SUM(NVL(NMST.NEBIKIKIN, 0)) + SUM(NVL(NMST.TESURYO, 0)) NYKNKIN
FROM
    S10T001T NMST
WHERE
        NMST.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
    AND NMST.SHOPCD = #{shopcd,jdbcType=VARCHAR}
    AND NMST.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
    AND NMST.GETSUJIPRCSJISSIDD = '00000000'
    AND NMST.YUKOKBN = '1'

SELECT
    SUM(NVL(NYKNKIN, 0) + NVL(NEBIKIKIN,0)  +  NVL(TESURYO,0)) NYKNKIN
FROM
    S10T001T
WHERE
    APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
    AND SHOPCD = #{shopcd,jdbcType=VARCHAR}
    AND SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
    AND SKYPRCSJISSIDD = '00000000'
    AND YUKOKBN = '1'

SELECT COUNT(*) CNT
FROM ( SELECT NMST.NYKNDD, NMST.KAISHUTNSHACD, NMST.SKYSAKICD, NMST.DNPYNO, NMST.NYKNKIND, SKSM.JIGYOSHOCD, SKSM.SKYSAKINMN1, SYKM.MOJISETTEIATAI
FROM S10T001T NMST, S02M017T SKSM, S02M006T SYKM WHERE NMST.APKIHONCD = SKSM.APKIHONCD(+) AND NMST.SHOPCD = SKSM.SHOPCD(+) AND NMST.SKYSAKICD = SKSM.SKYSAKICD(+) AND SYKM.APKIHONCD(+)= '000' AND SYKM.SHOPCD (+)= '000' AND SYKM.SETTEINO (+)= '050' AND SYKM.RCRDKBN (+)= 'M' AND SYKM.SETTEICD (+)= NMST.NYKNKIND
AND SYKM.SETTEICD IN
#{kinshu}
AND NMST.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND NMST.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND NMST.YUKOKBN = '1'
AND NMST.INPTUNYOYMD = #{prcsdd,jdbcType=VARCHAR}
AND ( NMST.NYKNDD BETWEEN #{nyknddstr,jdbcType=VARCHAR} AND #{nyknddend,jdbcType=VARCHAR} )
AND SKSM.JIGYOSHOCD = #{jigyoshosentaku,jdbcType=VARCHAR}
GROUP BY NMST.NYKNDD, NMST.KAISHUTNSHACD, NMST.SKYSAKICD, NMST.DNPYNO, NMST.NYKNKIND, SKSM.JIGYOSHOCD, SKSM.SKYSAKINMN1, SYKM.MOJISETTEIATAI ) A

SELECT
    MIN(SKYSHIMEDYDM || SKYSHIMEDD) SKYSHIMEDYDMDD
FROM
    S10T001T
WHERE
        APKIHONCD     = #{apkihoncd, jdbcType=VARCHAR}
    AND SHOPCD        = #{shopcd, jdbcType=VARCHAR}
    AND DNPYNO        = #{dnpyno, jdbcType=VARCHAR}
    AND SKYSAKICD     = #{skysakicd, jdbcType=VARCHAR}
    AND SKYSHIMEDYDM  IS NOT NULL
    AND YUKOKBN       = '1'
